 static RecoilDoor Door(Transform parent,Vector2 p,string name,string target,string spawn){var root=G(name,parent,p);B("Door frame",p,new Vector2(1.35f,2.6f),0x59665d,-1,root);B("Door leaf",p,new Vector2(1.13f,2.38f),0x414e43,0,root);B("Door inset",p+Vector2.up*.48f,new Vector2(.65f,.55f),0x223934,1,root);B("Handle",p+new Vector2(.37f,-.12f),new Vector2(.14f,.045f),0xa39b78,2,root);var d=root.gameObject.AddComponent<RecoilDoor>();d.requiresClue=false;d.completesLevel=false;d.destinationScene=target;d.destinationSpawn=spawn;d.interactionPrompt="E / "+name;d.openedMessage=name;Text(name=="RETURN TO CORRIDOR"?"CORRIDOR":name,p+Vector2.up*1.52f,root);return d;}
 static void Lamp(Transform parent,float x,float y,float intensity=.3f){var t=G("Ceiling fixture",parent,new Vector2(x,y));B("Shade",t.position,new Vector2(.7f,.1f),0x899381,-2,t);var child=G("Light - fixture child",t,t.position);var light=child.gameObject.AddComponent<RecoilLight2D>();light.radius=3.2f;light.intensity=intensity;}
