   for(int i=0;i<2;i++){float x=3.4f+i*1.5f;B("Dirty mirror",new Vector2(x,1.85f),new Vector2(1,1.05f),0x607777,-4,parent);B("Sink basin",new Vector2(x,.9f),new Vector2(1.1f,.24f),0xa2aa98,-2,parent);B("Drain pipe",new Vector2(x,.46f),new Vector2(.1f,.65f),0x485b50,-3,parent);B("Tap",new Vector2(x,1.12f),new Vector2(.1f,.22f),0x788578,-1,parent);}
   for(int i=0;i<2;i++){float x=6.5f+i*1.2f;B("Cubicle partition",new Vector2(x,1.22f),new Vector2(.1f,2.44f),0x4a635a,-3,parent);B("Cubicle door",new Vector2(x+.5f,1.2f),new Vector2(.85f,2.2f),0x677d6f,-2,parent);B("Door latch",new Vector2(x+.8f,1.25f),new Vector2(.08f,.1f),0xa7aa90,-1,parent);}Text("WASH BASINS",new Vector2(4.1f,3),parent);
  }else if(kind==1){for(int i=0;i<7;i++){float x=3.1f+i*1.15f;Cabinet(parent,x,0,0x506c5d);B("Locker vent",new Vector2(x,1.9f),new Vector2(.55f,.06f),0x263d33,-1,parent);}B("Changing bench",new Vector2(6,.46f),new Vector2(4.5f,.17f),0x786345,-1,parent);for(int i=-1;i<=1;i+=2)B("Bench leg",new Vector2(6+i*1.8f,.21f),new Vector2(.09f,.42f),0x364a3d,-1,parent);
  }else if(kind==2){for(int i=0;i<5;i++){float x=3.2f+i*2.1f;B("Archive shelving",new Vector2(x,1.4f),new Vector2(1.65f,2.8f),0x4d5c4c,-4,parent);for(int row=0;row<4;row++){B("Shelf",new Vector2(x,.35f+row*.67f),new Vector2(1.7f,.08f),0x888974,-2,parent);for(int box=0;box<4;box++)B("Archive box",new Vector2(x-.57f+box*.37f,.6f+row*.67f),new Vector2(.31f,.4f),box%2==0?0x827557:0x636f57,-3,parent);}}Text("RECORDS / PERSONNEL",new Vector2(width*.55f,3.4f),parent);
  }else if(kind==5){B("Conference table",new Vector2(9,.85f),new Vector2(7,.18f),0x837354,-2,parent);for(int i=0;i<5;i++)B("Chair",new Vector2(6.2f+i*1.4f,.64f),new Vector2(.6f,1.1f),0x48533e,-3,parent);B("Wall board",new Vector2(10,2.3f),new Vector2(4.4f,1.4f),0x384b3f,-5,parent);Text("PRODUCTION REVIEW",new Vector2(10,2.4f),parent);Cabinet(parent,14,0);
  }else{Desk(parent,4.5f,0);Desk(parent,kind==4?8.5f:8,0);Cabinet(parent,width-1.1f,0);B("Wall paperwork",new Vector2(6.3f,2.35f),new Vector2(2.4f,1),0x786d4f,-5,parent);if(kind==4){B("Visitor sofa",new Vector2(10,.65f),new Vector2(2.1f,1.1f),0x3d5140,-4,parent);Text("MANAGER",new Vector2(6.8f,3.2f),parent);}}
