 static void MakeRoom(int index){
  var source=EditorSceneManager.OpenScene("Assets/Scenes/RecoilServiceStore.unity",OpenSceneMode.Single);string path=Folder+files[index]+".unity";if(File.Exists(path))throw new Exception("Room scene already exists: "+path);EditorSceneManager.SaveScene(source,path,true);var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var w=World(scene);w.name="RECOIL - "+names[index];w.locationLabel=names[index];w.enableCheckpoint=false;w.legacyEvidenceEnabled=false;w.startWithWaterGun=false;w.objectiveWithoutCard="Explore the room. Return through the door to the factory corridor.";w.objectiveWithCard=w.objectiveWithoutCard;
  foreach(var t in w.transform.Cast<Transform>().ToArray())if(t.name=="01 Background"||t.name=="02 Terrain"||t.name=="03 Props and objectives"||t.name=="Store Entrance Spawn")UnityEngine.Object.DestroyImmediate(t.gameObject);
  var s=new SerializedObject(w);s.FindProperty("clue").objectReferenceValue=null;s.FindProperty("solidObjects").arraySize=0;s.ApplyModifiedPropertiesWithoutUndo();float width=widths[index];var environment=G("Room architecture - editable",w.transform,Vector2.zero);B("Room back wall",new Vector2(width/2,1.9f),new Vector2(width,3.8f),index==0?0x455e54:0x525d4e,-10,environment);B("Dado",new Vector2(width/2,.65f),new Vector2(width,1.3f),0x30483a,-8,environment);B("Room floor",new Vector2(width/2,-.25f),new Vector2(width+1,.5f),0x4a5c50,0,environment,true);B("Left wall",new Vector2(-.2f,1.9f),new Vector2(.4f,3.8f),0x536352,0,environment,true);B("Right wall",new Vector2(width+.2f,1.9f),new Vector2(.4f,3.8f),0x536352,0,environment,true);B("Room ceiling",new Vector2(width/2,4),new Vector2(width+1,.4f),0x475745,0,environment,true);Furnish(environment,index,width);
  var entrance=Door(environment,new Vector2(1.2f,1.25f),"RETURN TO CORRIDOR",Factory,"Room Return - "+files[index]);Set(w,"door",entrance.transform);var spawn=G("Room Entrance Spawn",w.transform,new Vector2(2.6f,.845f));Set(w,"spawnPoint",spawn);Set(w,"checkpointPoint",spawn);w.Player.Position=spawn.position;
  var lighting=w.GetComponentsInChildren<RecoilLighting2D>().First();foreach(var child in lighting.transform.Cast<Transform>().ToArray())if(child.name!="Darkness Layer")UnityEngine.Object.DestroyImmediate(child.gameObject);var area=G("Room Dark Area",w.transform,new Vector2(width/2,1.9f));area.localScale=new Vector3(width,3.8f,1);var overlay=lighting.GetComponentsInChildren<SpriteRenderer>().First(r=>r.name=="Darkness Layer");lighting.Configure(w.Player.transform,area,overlay);lighting.outdoorAmbient=.18f;lighting.unlitAmbientScale=.3f;for(float x=3.5f;x<width;x+=4.5f)Lamp(environment,x,3.65f,index==0?.27f:.3f);
  var wave=w.GetComponentsInChildren<SoundWaveManager>(true).First();wave.buildingBroadcastsEnabled=false;var ws=new SerializedObject(wave);ws.FindProperty("controlArea").objectReferenceValue=area;ws.ApplyModifiedPropertiesWithoutUndo();var camera=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<RecoilCameraController>()).First();camera.viewSize=index==0?2.7f:3.2f;camera.followOffset=new Vector2(1.2f,1.2f);camera.minimumY=camera.maximumY=1.9f;camera.maximumMouseOffset=1;camera.limitDownwardMouseOffset=true;camera.maximumDownwardMouseOffset=.25f;EditorSceneManager.SaveScene(scene,path);
 }
 public static void Build(){
  if(EditorApplication.isPlaying)throw new Exception("Exit Play first.");Directory.CreateDirectory(Folder);var original=SceneManager.GetActiveScene();var scene=EditorSceneManager.OpenScene(Factory,OpenSceneMode.Single);Directory.CreateDirectory("Backups/FactoryNestedRooms");EditorSceneManager.SaveScene(scene,"Backups/FactoryNestedRooms/RecoilFactoryInterior_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity",true);var w=World(scene);var so=new SerializedObject(w);square=(Sprite)so.FindProperty("sceneSprite").objectReferenceValue;material=(Material)so.FindProperty("sceneMaterial").objectReferenceValue;var old=w.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Office suites - factory refit");UnityEngine.Object.DestroyImmediate(old.gameObject);var corridors=G("Office corridors and third-level room doors",w.transform,Vector2.zero);
  for(int floor=0;floor<3;floor++){float y=floors[floor];var root=G("Floor "+(floor+2)+" public corridor",corridors,new Vector2(0,y));B("Corridor wall",new Vector2(14,y+2),new Vector2(28,3.9f),0x4b554a,-9,root);B("Corridor dado",new Vector2(14,y+.65f),new Vector2(28,1.3f),0x304238,-8,root);B("Corridor skirting",new Vector2(14,y+.08f),new Vector2(28,.12f),0x1b2e24,-7,root);for(int n=0;n<2;n++){int index=floor*2+n;float x=n==0?5:13;Door(root,new Vector2(x,y+1.25f),names[index],Folder+files[index]+".unity","Room Entrance Spawn");G("Room Return - "+files[index],w.transform,new Vector2(x+1.3f,y+.845f));}for(int n=0;n<3;n++)Lamp(root,3+n*8,y+3.65f,.24f);
   var open=G(floor==0?"Open break and drinking alcove":floor==1?"Open reception waiting area":"Open clerks work area",root,new Vector2(18,y));B("Open alcove wall",new Vector2(22,y+2),new Vector2(7.5f,3.9f),0x5b6353,-8,open);Text(floor==0?"BREAK AREA":floor==1?"RECEPTION":"CLERKS",new Vector2(22,y+3.2f),open);
   if(floor==0){B("Water cooler",new Vector2(19.2f,y+.65f),new Vector2(.65f,1.3f),0x778471,-4,open);B("Water bottle",new Vector2(19.2f,y+1.55f),new Vector2(.42f,.6f),0x617e79,-3,open);B("Bench",new Vector2(23,y+.46f),new Vector2(3.8f,.18f),0x807057,-3,open);B("Notice board",new Vector2(22,y+2.15f),new Vector2(2.5f,1),0x776b4b,-5,open);}else if(floor==1){B("Reception counter",new Vector2(20,y+.55f),new Vector2(2.6f,1.1f),0x726b51,-4,open);for(int i=0;i<3;i++)B("Waiting chair",new Vector2(23+i*.85f,y+.65f),new Vector2(.65f,1.15f),0x3d5240,-4,open);}else{Desk(open,20,y);Desk(open,24,y);}
  }
  EditorSceneManager.SaveScene(scene,Factory);for(int i=0;i<files.Length;i++)MakeRoom(i);var list=EditorBuildSettings.scenes.ToList();foreach(var file in files){string path=Folder+file+".unity";if(!list.Any(s=>s.path==path))list.Add(new EditorBuildSettingsScene(path,true));}EditorBuildSettings.scenes=list.ToArray();AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(Factory,OpenSceneMode.Single);Debug.Log("FACTORY_NESTED_ROOMS_COMPLETE: 6 third-level scenes, 3 open corridor spaces, registered build settings.");
 }
 public static void FinishLabelsAndValidate(){foreach(var file in files){var scene=EditorSceneManager.OpenScene(Folder+file+".unity",OpenSceneMode.Single);foreach(var text in scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<TextMesh>()))if(text.text=="RETURN TO CORRIDOR")text.text="CORRIDOR";EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}ValidateAndCapture();}
 public static void ValidateAndCapture(){
  var build=EditorBuildSettings.scenes;foreach(var file in files){var path=Folder+file+".unity";if(!build.Any(s=>s.path==path&&s.enabled))throw new Exception("Room not enabled in build: "+file);var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var w=World(scene);var player=w.Player;if(new SerializedObject(player).FindProperty("world").objectReferenceValue!=w)throw new Exception("Wrong player owner: "+file);var cam=(Camera)new SerializedObject(w).FindProperty("cam").objectReferenceValue;if(!cam||cam.gameObject.scene!=scene)throw new Exception("Wrong camera reference: "+file);foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(t.GetComponents<Component>().Any(c=>c==null))throw new Exception("Missing script: "+file+" / "+t.name);var door=w.GetComponentsInChildren<RecoilDoor>().Single();if(door.destinationScene!=Factory||door.destinationSpawn!="Room Return - "+file)throw new Exception("Invalid return door: "+file);Debug.Log("NESTED_ROOM_VALIDATED "+file);}
  FourStoreyFactoryBuilder.CaptureLayout();
  foreach(int index in new[]{0,1,2,3,4,5}){var scene=EditorSceneManager.OpenScene(Folder+files[index]+".unity",OpenSceneMode.Single);var roots=scene.GetRootGameObjects();foreach(var c in roots.SelectMany(r=>r.GetComponentsInChildren<RecoilCameraController>()))c.enabled=false;foreach(var lighting in roots.SelectMany(r=>r.GetComponentsInChildren<RecoilLighting2D>()))lighting.enabled=false;foreach(var sprite in roots.SelectMany(r=>r.GetComponentsInChildren<SpriteRenderer>()))if(sprite.name=="Darkness Layer")sprite.enabled=false;var camera=roots.SelectMany(r=>r.GetComponentsInChildren<Camera>()).First();camera.orthographic=true;camera.orthographicSize=Mathf.Max(2.6f,widths[index]/3.2f+.2f);camera.transform.position=new Vector3(widths[index]/2,1.9f,-10);camera.transform.rotation=Quaternion.identity;var rt=new RenderTexture(1600,1000,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes("output/level-previews/"+files[index]+"-layout.png",tex.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}
  Debug.Log("NESTED_ROOM_VALIDATION_AND_CAPTURE_COMPLETE");
 }

